def choose_move(observation):
    px, py = observation['self_position']
    enemies = observation['opponent_position']
    obstacles = set(observation['obstacles'])
    width, height = observation['grid_width'], observation['grid_height']
    # Determine closest opponent
    ox, oy = enemies
    dx = dy = 0
    if ox > px and (px + 1, py) not in obstacles and px + 1 < width:
        dx = 1
    elif ox < px and (px - 1, py) not in obstacles and px - 1 >= 0:
        dx = -1
    elif oy > py and (px, py + 1) not in obstacles and py + 1 < height:
        dy = 1
    elif oy < py and (px, py - 1) not in obstacles and py - 1 >= 0:
        dy = -1
    else:
        if (px + 1 < width and (px + 1, py) not in obstacles):
            dx = 1
        elif (px - 1 >= 0 and (px - 1, py) not in obstacles):
            dx = -1
        elif (py + 1 < height and (px, py + 1) not in obstacles):
            dy = 1
        elif (py - 1 >= 0 and (px, py - 1) not in obstacles):
            dy = -1
        else:
            dx, dy = 0, 0
    return [dx, dy]
